function priceEvent(input) {
  const loc = LOCATIONS[input.city];
  const pk = EVENT.pkgs[input.pkg];
  if (!loc) throw new Error("Unknown city");
  if (!pk) throw new Error("Unknown package");
  const guests = Math.max(9, Math.min(80, parseInt(input.guests, 10) || 0));
  const food = EVENT.food[input.food] ? input.food : pk.food;
  const drinks = EVENT.drinks[input.drinks] ? input.drinks : pk.drinks;
  const extras = new Set([...(input.extras || []).filter(x => EVENT.extras[x]), ...pk.extras]);

  const day = new Date(input.date + "T12:00:00").getDay();
  const hour = parseInt(input.time, 10) + (String(input.time).endsWith("30") ? 0.5 : 0);
  if (input.pkg === "break" && !(day >= 1 && day <= 5 && hour + pk.hrs <= 17)) throw new Error("Game Break is weekdays before 5 PM only");

  const lines = [];   // { label, amount, otc: {itemId, quantity} | null }
  const billed = Math.max(guests, pk.minGuests || 0);
  lines.push({ label: `${pk.name} · ${billed} × $${pk.pp}`, amount: billed * pk.pp, kind: "package" });

  // Food/drinks: the package price assumes its default; upgrades/downgrades are the difference.
  // In OTC each chosen option is an item line item so the kitchen sees it on the order.
  for (const [group, chosen, base] of [["food", food, pk.food], ["drinks", drinks, pk.drinks]]) {
    const c = EVENT[group][chosen], b = EVENT[group][base];
    const diff = c.pp - b.pp;
    lines.push({ label: diff ? `${c.name} (vs ${b.name.toLowerCase()}) · ${guests} × ${diff > 0 ? "+" : "−"}$${Math.abs(diff)}` : `${c.name} (included)`,
                 amount: guests * diff, kind: group, otc: { itemId: c.itemId, quantity: guests } });
  }
  for (const x of extras) {
    const e = EVENT.extras[x], included = pk.extras.includes(x);
    lines.push({ label: included ? `${e.name} (included)` : (e.flat ? e.name : `${e.name} · ${guests} × $${e.pp}`),
                 amount: included ? 0 : (e.flat || guests * e.pp), kind: "extra", otc: { itemId: e.itemId, quantity: e.flat ? 1 : guests } });
  }
  let sub = lines.reduce((a, l) => a + l.amount, 0);
  const notes = [];
  if ((day === 5 || day === 6) && hour >= 17 && sub < EVENT.weekendNightMin) {
    lines.push({ label: "Friday/Saturday night minimum spend", amount: EVENT.weekendNightMin - sub, kind: "minimum" });
    sub = EVENT.weekendNightMin;
    notes.push(`Friday/Saturday nights have a $${EVENT.weekendNightMin} minimum.`);
  }
  const lounges = Math.ceil(guests / EVENT.perLounge);
  if (lounges > loc.lounges) notes.push(`Needs ${lounges} lounges; ${loc.name} has ${loc.lounges}. Staff will plan rotations or a buyout.`);
  const tax = sub * loc.tax, gratuity = sub * EVENT.gratuity, total = sub + tax + gratuity;
  const r2 = n => Math.round(n * 100) / 100;
  return { city: input.city, date: input.date, time: input.time, guests, pkg: input.pkg, pkgName: pk.name, hrs: pk.hrs, food, drinks,
           extras: [...extras], lounges: Math.min(lounges, loc.lounges), lines, notes,
           subtotal: r2(sub), tax: r2(tax), gratuity: r2(gratuity), total: r2(total), deposit: r2(total * EVENT.depositPct) };
}
function endTime(start, hrs) {
  const [h, m] = start.split(":").map(Number);
  const mins = h * 60 + m + Math.round(hrs * 60);
  return `${String(Math.floor(mins / 60)).padStart(2, "0")}:${String(mins % 60).padStart(2, "0")}:00`;
}
var KEY="gnl-otc-demo-v1";
function load(){try{return JSON.parse(localStorage.getItem(KEY))||null}catch(e){return null}}
var S=load()||{holds:{},rsvps:{},use:{},log:[]};
function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}}
function log(msg){S.log.unshift({at:new Date().toISOString(),msg:msg});S.log.length=Math.min(S.log.length,100);save();}
function seeded(d,h,g){var s=[].reduce.call(d+h+g,function(a,c){return (a*31+c.charCodeAt(0))>>>0},7);var busy=h>=18&&h<=20?4:h>=14?2:1;return Math.min(10,busy+(s%3));}
