function tally(id){var l=Object.values(S.rsvps).filter(function(r){return r.holdId===id});var diet={};l.filter(function(r){return r.attending==="yes"}).forEach(function(r){(r.diet||[]).forEach(function(d){diet[d]=(diet[d]||0)+1})});
  return {responses:l.length,yes:l.filter(function(r){return r.attending==="yes"}).length,maybe:l.filter(function(r){return r.attending==="maybe"}).length,no:l.filter(function(r){return r.attending==="no"}).length,diet:diet,allergies:l.filter(function(r){return r.allergies}).length};}
function pub(h){return {id:h.id,company:h.company,city:h.city,date:h.quote.date,time:h.quote.time,guests:h.quote.guests,pkgName:h.quote.pkgName,hrs:h.quote.hrs,status:h.status,expiresAt:h.expiresAt,orderNumber:h.orderNumber,rsvp:tally(h.id)}}
