    for(var hh=h0;hh<Math.max(h1,h0+1);hh++){var free=loc.lounges-used(g,q.date,hh);if(free<lounges)return J(409,{error:"That time is full: "+free+" lounges free at "+hh+":00, "+lounges+" needed. Try another start time."});}
